class Solution:
    def countSubmatrices(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        run = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if grid[i][j] <= k:
                    run[i][j] = run[i][j-1] + 1 if j > 0 and run[i][j-1] > 0 and grid[i][j-1] >= grid[i][j] else 1
        ans = 0
        for top in range(m):
            mn = run[top][:]
            for bot in range(top, m):
                for j in range(n):
                    if run[bot][j] < mn[j]: mn[j] = run[bot][j]
                ans += sum(mn)
        return ans

