class Solution {
public:
    long long countSubmatrices(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> run(m, vector<int>(n, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] <= k)
                    run[i][j] = (j > 0 && run[i][j-1] > 0 && grid[i][j-1] >= grid[i][j]) ? run[i][j-1] + 1 : 1;
        long long ans = 0;
        for (int top = 0; top < m; top++) {
            vector<int> mn = run[top];
            for (int bot = top; bot < m; bot++) {
                long long s = 0;
                for (int j = 0; j < n; j++) { mn[j] = min(mn[j], run[bot][j]); s += mn[j]; }
                ans += s;
            }
        }
        return ans;
    }
};

