class Solution {
public:
    long long countSubmatrices(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<int>> run(m, vector<int>(n, 0));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] <= k)
                    run[i][j] = (j > 0 && run[i][j-1] > 0 && grid[i][j-1] >= grid[i][j]) ? run[i][j-1] + 1 : 1;
        long long ans = 0;
        for (int j = 0; j < n; j++) {
            vector<pair<int,long long>> st; long long cur = 0;
            for (int i = 0; i < m; i++) {
                int v = run[i][j]; long long cnt = 1;
                while (!st.empty() && st.back().first >= v) {
                    cur -= st.back().first * st.back().second;
                    cnt += st.back().second; st.pop_back();
                }
                cur += v * cnt; st.push_back({v, cnt});
                ans += cur;
            }
        }
        return ans;
    }
};

