class Solution {
    public long countSubmatrices(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int[][] run = new int[m][n];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] <= k)
                    run[i][j] = (j > 0 && run[i][j-1] > 0 && grid[i][j-1] >= grid[i][j]) ? run[i][j-1] + 1 : 1;
        long ans = 0;
        for (int j = 0; j < n; j++) {
            ArrayDeque<long[]> st = new ArrayDeque<>(); long cur = 0;
            for (int i = 0; i < m; i++) {
                long v = run[i][j], cnt = 1;
                while (!st.isEmpty() && st.peek()[0] >= v) {
                    long[] b = st.pop(); cur -= b[0] * b[1]; cnt += b[1];
                }
                cur += v * cnt; st.push(new long[]{v, cnt});
                ans += cur;
            }
        }
        return ans;
    }
}

